# Generated by build.py from recipe.yml for recipe http-replay-exchanges-without-the-server. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/report.csv'), "region,total`nnorth,12`nsouth,7`n")
[IO.File]::WriteAllText((Join-Path $PWD 'record.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Starts surl on port `$1, records each name below into rec/ (the response head in`n# <name>.head, the body in <name>), then stops the server. Usage: sh record.sh <port>`nurl=`"http://127.0.0.1:`$1`"`nsurl -s --directory site `"`$url/`" > /dev/null 2>&1 &`npid=`$!`ntries=0`nuntil curl -s -o /dev/null --max-time 2 `"`$url/`"; do      # wait until it answers, 10 s at most`n  tries=`$((tries + 1)); [ `"`$tries`" -ge 50 ] && { kill `"`$pid`"; exit 1; }`n  sleep 0.2`ndone`nmkdir -p rec`nfor name in hello.txt report.csv missing.txt; do`n  curl -s --max-time 10 -D `"rec/`$name.head`" -o `"rec/`$name`" `"`$url/`$name`"`n  echo `"recorded `$name: `$(head -n 1 `"rec/`$name.head`" | tr -d '\r')`"`ndone`nkill `"`$pid`"; wait `"`$pid`" 2> /dev/null`ncurl -s -o /dev/null --max-time 5 `"`$url/hello.txt`"`necho `"server stopped: curl exit `$?`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'replay.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Fetches the recorded body of `$1 with curl from a file: URL, so no server is needed.`n# Usage: sh replay.sh <name>`ndir=`$(cd rec && { pwd -W 2> /dev/null || pwd; })   # pwd -W: the Windows path, in Git Bash`ncase `$dir in /*) base=`"file://`$dir`" ;; *) base=`"file:///`$dir`" ;; esac`ncurl -sS --max-time 10 `"`$(printf '%s/%s' `"`$base`" `"`$1`" | sed 's/ /%20/g')`"`n")
sh record.sh 8080 && sh replay.sh hello.txt
